#include "vkaether/database.hpp"
#include <filesystem>
#include <sstream>
#include <stdexcept>
namespace vkaether {
namespace { void check(sqlite3* db,int rc,const char* op){if(rc!=SQLITE_OK&&rc!=SQLITE_DONE&&rc!=SQLITE_ROW)throw std::runtime_error(std::string(op)+": "+(db?sqlite3_errmsg(db):"sqlite error"));} struct Stmt{sqlite3* db;sqlite3_stmt* p{};Stmt(sqlite3*d,const char*s):db(d){check(db,sqlite3_prepare_v2(db,s,-1,&p,nullptr),"prepare");}~Stmt(){sqlite3_finalize(p);}}; }
Database::Database(const std::filesystem::path& path){if(path.has_parent_path())std::filesystem::create_directories(path.parent_path());int rc=sqlite3_open_v2(path.string().c_str(),&db_,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX,nullptr);if(rc!=SQLITE_OK){std::string e=db_?sqlite3_errmsg(db_):"allocation failure";if(db_)sqlite3_close(db_);db_=nullptr;throw std::runtime_error(e);}sqlite3_busy_timeout(db_,3000);execute("PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA temp_store=MEMORY; CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,balance INTEGER NOT NULL DEFAULT 1000,experience INTEGER NOT NULL DEFAULT 0,level INTEGER NOT NULL DEFAULT 1,last_bonus INTEGER NOT NULL DEFAULT 0); CREATE INDEX IF NOT EXISTS idx_users_balance ON users(balance DESC);");}
Database::~Database(){if(db_)sqlite3_close(db_);}
void Database::execute(const char*s){char*e=nullptr;int rc=sqlite3_exec(db_,s,nullptr,nullptr,&e);if(rc!=SQLITE_OK){std::string m=e?e:sqlite3_errmsg(db_);sqlite3_free(e);throw std::runtime_error(m);}}
UserState Database::get_user(std::int64_t id){std::lock_guard l(mutex_);Stmt a(db_,"INSERT OR IGNORE INTO users(id) VALUES(?1)");sqlite3_bind_int64(a.p,1,id);check(db_,sqlite3_step(a.p),"insert user");Stmt q(db_,"SELECT id,balance,experience,level FROM users WHERE id=?1");sqlite3_bind_int64(q.p,1,id);check(db_,sqlite3_step(q.p),"select user");return{sqlite3_column_int64(q.p,0),sqlite3_column_int64(q.p,1),sqlite3_column_int64(q.p,2),sqlite3_column_int64(q.p,3)};}
std::int64_t Database::daily_bonus(std::int64_t id,std::int64_t amount){std::lock_guard l(mutex_);execute("BEGIN IMMEDIATE");try{Stmt q(db_,"INSERT OR IGNORE INTO users(id) VALUES(?1)");sqlite3_bind_int64(q.p,1,id);check(db_,sqlite3_step(q.p),"insert");Stmt u(db_,"UPDATE users SET balance=balance+?1,last_bonus=unixepoch()/86400 WHERE id=?2 AND last_bonus<unixepoch()/86400");sqlite3_bind_int64(u.p,1,amount);sqlite3_bind_int64(u.p,2,id);check(db_,sqlite3_step(u.p),"bonus");bool changed=sqlite3_changes(db_)>0;execute("COMMIT");return changed?amount:0;}catch(...){execute("ROLLBACK");throw;}}
bool Database::work(std::int64_t id,std::int64_t reward){std::lock_guard l(mutex_);Stmt q(db_,"INSERT OR IGNORE INTO users(id) VALUES(?1)");sqlite3_bind_int64(q.p,1,id);check(db_,sqlite3_step(q.p),"insert");Stmt u(db_,"UPDATE users SET balance=balance+?1,experience=experience+2,level=1+(experience+2)/100 WHERE id=?2");sqlite3_bind_int64(u.p,1,reward);sqlite3_bind_int64(u.p,2,id);check(db_,sqlite3_step(u.p),"work");return true;}
bool Database::transfer(std::int64_t from,std::int64_t to,std::int64_t amount){if(from==to||amount<=0)return false;std::lock_guard l(mutex_);execute("BEGIN IMMEDIATE");try{Stmt a(db_,"INSERT OR IGNORE INTO users(id) VALUES(?1)");sqlite3_bind_int64(a.p,1,from);check(db_,sqlite3_step(a.p),"sender");Stmt b(db_,"INSERT OR IGNORE INTO users(id) VALUES(?1)");sqlite3_bind_int64(b.p,1,to);check(db_,sqlite3_step(b.p),"receiver");Stmt d(db_,"UPDATE users SET balance=balance-?1 WHERE id=?2 AND balance>=?1");sqlite3_bind_int64(d.p,1,amount);sqlite3_bind_int64(d.p,2,from);check(db_,sqlite3_step(d.p),"debit");if(sqlite3_changes(db_)!=1){execute("ROLLBACK");return false;}Stmt c(db_,"UPDATE users SET balance=balance+?1 WHERE id=?2");sqlite3_bind_int64(c.p,1,amount);sqlite3_bind_int64(c.p,2,to);check(db_,sqlite3_step(c.p),"credit");execute("COMMIT");return true;}catch(...){execute("ROLLBACK");throw;}}
std::string Database::top(std::size_t limit){std::lock_guard l(mutex_);Stmt q(db_,"SELECT id,balance FROM users ORDER BY balance DESC LIMIT ?1");sqlite3_bind_int64(q.p,1,static_cast<sqlite3_int64>(limit));std::ostringstream o;std::size_t n=1;while(sqlite3_step(q.p)==SQLITE_ROW)o<<n++<<". ID "<<sqlite3_column_int64(q.p,0)<<" — "<<sqlite3_column_int64(q.p,1)<<" coins\\n";return o.str().empty()?"Пока рейтинг пуст.":o.str();}
}